#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    long long a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    // Compute node value
    auto node_val = [&](int v) -> long long {
        long long s = 0;
        int x = v;
        if(x == 0) return a[0];
        while(x > 0){ s += a[x % 10]; x /= 10; }
        return s;
    };

    auto path_val = [&](const vector<int>& path) -> long long {
        long long s = 0;
        for(int v : path) s += node_val(v);
        return s;
    };

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){ return chrono::duration_cast<chrono::milliseconds>(now() - start_time).count(); };

    mt19937 rng(42);
    vector<int> best_path;
    long long best_score = LLONG_MIN;

    while(elapsed_ms() < 3800){
        int sv = rng() % n + 1;
        vector<int> path;
        vector<bool> used(n+1, false);
        path.push_back(sv);
        used[sv] = true;

        auto extend_back = [&]() -> bool {
            int tail = path.back();
            int pick = -1; long long bv = LLONG_MIN;
            for(int v : adj[tail]) if(!used[v]){
                long long val = node_val(v) + (long long)(adj[v].size());
                if(val > bv){ bv = val; pick = v; }
            }
            if(pick < 0) return false;
            path.push_back(pick); used[pick] = true;
            return true;
        };

        auto extend_front = [&]() -> bool {
            int head = path[0];
            int pick = -1; long long bv = LLONG_MIN;
            for(int v : radj[head]) if(!used[v]){
                long long val = node_val(v) + (long long)(radj[v].size());
                if(val > bv){ bv = val; pick = v; }
            }
            if(pick < 0) return false;
            path.insert(path.begin(), pick); used[pick] = true;
            return true;
        };

        for(int r = 0; r < 4; r++){
            while(extend_back());
            while(extend_front());
        }

        long long sc = path_val(path);
        if(sc > best_score){ best_score = sc; best_path = path; }
    }

    cout << best_path.size() << "\n";
    for(int i = 0; i < (int)best_path.size(); i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
}
